uint32_t* createNeighborTable(Particle *sortedParticles, const size_t &particleCount) {
    uint32_t* table = new uint32_t[TABLE_SIZE];

    // Initialize all entries to NO_PARTICLE
    for (int i = 0; i < TABLE_SIZE; i++) {
        table[i] = NO_PARTICLE;
    }

    // Fill the table with first particle indices for each hash
    if (particleCount > 0) {
        uint16_t lastHash = sortedParticles[0].hash;
        table[lastHash] = 0;

        for (size_t i = 1; i < particleCount; i++) {
            if (sortedParticles[i].hash != lastHash) {
                lastHash = sortedParticles[i].hash;
                table[lastHash] = static_cast<uint32_t>(i);
            }
        }
    }

    return table;
}

